package org.apache.commons.lang;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for NumberUtils.createNumber to maximize branch and line coverage.
 * Note: Since createInteger, createLong, etc., are internal/helper methods 
 * used by createNumber, this test suite focuses on the logic flow of createNumber.
 */
public class NumberUtils_createNumber_TriageGen0Test {

    @Test
    public void testCreateNumber_Null() throws NumberFormatException {
        assertNull(NumberUtils.createNumber(null));
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_EmptyString() throws NumberFormatException {
        NumberUtils.createNumber("");
    }

    @Test
    public void testCreateNumber_DoubleDashProtection() throws NumberFormatException {
        assertNull(NumberUtils.createNumber("--123"));
    }

    @Test
    public void testCreateNumber_Hexadecimal() throws NumberFormatException {
        // Tests the val.startsWith("0x") branch
        Number number = NumberUtils.createNumber("0x10");
        assertTrue(number instanceof Integer);
        assertEquals(16, number.intValue());

        Number negHex = NumberUtils.createNumber("-0x10");
        assertEquals(-16, negHex.intValue());
    }

    @Test
    public void testCreateNumber_Integer() throws NumberFormatException {
        Number n = NumberUtils.createNumber("123");
        assertTrue(n instanceof Integer);
        assertEquals(123, n.intValue());
    }

    @Test
    public void testCreateNumber_Long() throws NumberFormatException {
        Number n = NumberUtils.createNumber("1234567890123");
        assertTrue(n instanceof Long);
        assertEquals(1234567890123L, n.longValue());
    }

    @Test
    public void testCreateNumber_BigInteger() throws NumberFormatException {
        String bigVal = "123456789012345678901234567890";
        Number n = NumberUtils.createNumber(bigVal);
        assertTrue(n instanceof BigInteger);
        assertEquals(new BigInteger(bigVal), n);
    }

    @Test
    public void testCreateNumber_FloatSuffix() throws NumberFormatException {
        Number n = NumberUtils.createNumber("12.34f");
        assertTrue(n instanceof Float);
        assertEquals(12.34F, ((Float) n).floatValue(), 0.001f);
    }

    @Test
    public void testCreateNumber_DoubleSuffix() throws NumberFormatException {
        Number n = NumberUtils.createNumber("12.34d");
        assertTrue(n instanceof Double);
        assertEquals(12.34D, ((Double) n).doubleValue(), 0.001);
    }

    @Test
    public void testCreateNumber_LongSuffix() throws NumberFormatException {
        Number n = NumberUtils.createNumber("123L");
        assertTrue(n instanceof Long);
        assertEquals(123L, n.longValue());
    }

    @Test
    public void testCreateNumber_BigIntegerSuffix() throws NumberFormatException {
        String bigVal = "123456789012345678901234567890L";
        Number n = NumberUtils.createNumber(bigVal);
        assertTrue(n instanceof BigInteger);
    }

    @Test
    public void testCreateNumber_DecimalAndExponent() throws NumberFormatException {
        Number n = NumberUtils.createNumber("1.23e2");
        // 1.23 * 10^2 = 123.0
        assertTrue(n instanceof Double || n instanceof BigDecimal);
        assertEquals(123.0, n.doubleValue(), 0.001);
    }

    @Test
    public void testCreateNumber_ScientificNotationNoDecimal() throws NumberFormatException {
        Number n = NumberUtils.createNumber("1e2");
        assertEquals(100.0, n.doubleValue(), 0.001);
    }

    @Test
    public void testCreateNumber_InvalidExponentPosition() {
        // expPos < decPos case
        try {
            NumberUtils.createNumber("1e2.3");
            fail("Should have thrown NumberFormatException");
        } catch (NumberFormatException e) {
            // Expected
        }
    }

    @Test
    public void testCreateNumber_FallbackToBigDecimal() throws NumberFormatException {
        // Test a case where Float/Double might fail or be too imprecise
        // Using a very large number that exceeds Double range but is valid for BigDecimal
        String huge = "1e1000"; 
        Number n = NumberUtils.createNumber(huge);
        assertTrue(n instanceof BigDecimal);
    }

    @Test
    public void testCreateNumber_InvalidSuffix() {
        try {
            NumberUtils.createNumber("123z");
            fail("Should have thrown NumberFormatException");
        } catch (NumberFormatException e) {
            // Expected
        }
    }

    @Test
    public void testCreateNumber_AllZerosLogic() throws NumberFormatException {
        // Testing the allZeros check logic via a float/double path
        Number n = NumberUtils.createNumber("0.000");
        assertNotNull(n);
        assertEquals(0.0, n.doubleValue(), 0.0);
    }

    @Test
    public void testCreateNumber_NegativeLongSuffix() throws NumberFormatException {
        Number n = NumberUtils.createNumber("-123L");
        assertEquals(-123L, n.longValue());
    }

    @Test
    public void testCreateNumber_DecimalWithNoMantissaPart() {
        // Tests logic around substring/indexOf
        try {
            NumberUtils.createNumber(".5");
            // Depending on implementation of createFloat/Double/BigDecimal, this might work or fail
        } catch (NumberFormatException e) {
            // Expected if the parser requires a leading digit
        }
    }

    @Test
    public void testCreateNumber_LargeFloatFallthrough() throws NumberFormatException {
        // A number too large for float, should fall through to Double or BigDecimal
        String large = "1e40f"; 
        Number n = NumberUtils.createNumber(large);
        // Since 1e40 is too big for float, it should try Double or BigDecimal
        assertNotNull(n);
    }
}
